<script setup lang="ts">
import {computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import GmItemPicker from '../../components/GmItemPicker.vue'
import {useGmWorkspace} from '../../stores/gm/useGmWorkspace'
import {useGmWorkspaceBindings} from '../../stores/gm/useGmWorkspace'
import {asyncPanel} from '../../asyncPanel'
import ItemCard from '../../components/ItemCard.vue'
import CatalogFilters from '../../components/CatalogFilters.vue'
import ItemCompare from '../../components/ItemCompare.vue'
import CurrencyRewardInputs from '../../components/CurrencyRewardInputs.vue'
import FavoriteButton from '../../components/FavoriteButton.vue'
import ItemCollection from '../../components/ItemCollection.vue'
import PlayerShortcuts from '../../components/PlayerShortcuts.vue'
import MailWorkbench from '../../components/MailWorkbench.vue'
import ItemQueue from '../../components/ItemQueue.vue'
import FieldError from '../../components/FieldError.vue'
import GmSceneBanner from '../../components/GmSceneBanner.vue'
const {mailPane,mailTextOpen,catalogFacets,compareItems,compareWarning,fullCatalogFilters,updateCatalogFilters,toggleCompare,policyLabel,fieldErrors,feedbackScope,busy,error,notice,page,search,rows,account,roles,selectedRole,catalogMeta,playerRevision,currentPlayerTarget,chooseSavedPlayer,action,reason,message,mailGold,mailCurrencies,mailTitle,templateAdjusted,hasMailCurrencies,mailAttachments,pendingId,category,templateId,templateVersion,categoryNames,sendable,loginState,onlineLabel,money,openCharacter,clearSession,draft,run,load,searchRows,go,select,preferenceRevision,preferenceWarning,preferenceChanged,addItem,makePreview,recipientSearchType,recipientSearch,recipientResults,recipientQueried,mailAllowedOnly,role,totalQuantity,findRecipient,pickRecipient,saveAsTemplate}=useGmWorkspaceBindings()

const workspace=useGmWorkspace()
const route=useRoute(),router=useRouter()
const draftOptions=computed(()=>Object.entries(workspace.drafts.drafts).filter(([,draft])=>draft.uid))
const workflowLabels=['选择目标','编辑奖励','核对预览','确认与结果']
const workflowStage=computed(()=>{
 if(workspace.pendingId||workspace.operationResult)return 4
 if(workspace.preview)return 3
 return account.value&&role.value&&!role.value.delete_flag?2:1
})
const workflowHint=computed(()=>{
 if(workspace.pendingId)return '提交结果待核对，请按原编号查询。'
 if(workspace.operationResult)return workspace.resultCommitted?'已取得提交结果，可查看投递详情。':'已取得原操作状态，请核对结果。'
 if(workspace.preview)return '预览已生成，请核对目标与奖励后确认。'
 return workflowStage.value===2?'目标已选定，编辑奖励后生成预览。':'先选择账号与收件角色。'
})
let restoring=false
watch(()=>[route.query.uid,route.query.charac_no],async ([uid,character])=>{restoring=true;await workspace.activate('mail',false);if(uid)await workspace.run(()=>workspace.setTarget(Number(uid),Number(character)||0));workspace.action='mail';restoring=false},{immediate:true})
watch(()=>[workspace.account?.uid,workspace.selectedRole],([uid,character])=>{if(!restoring&&uid)void router.replace({query:{...route.query,uid:String(uid),charac_no:character?String(character):undefined}})})
function switchDraft(value:string){const [uid,character]=value.split(':').map(Number);void router.replace({query:{...route.query,uid:String(uid),charac_no:character?String(character):undefined}})}

</script>
<template><div class="gm-workspace"><GmSceneBanner eyebrow="奖励运营" title="奖励编辑器" description="先选定收件角色，整理奖励，再预览确认与核对结果。"/><p v-if="workspace.drafts.versionWarning" role="status" class="warning">{{workspace.drafts.versionWarning}}</p><label v-if="draftOptions.length>1" class="draft-switcher">玩家奖励草稿<select :value="workspace.drafts.activeKey" :disabled="busy||!!pendingId" @change="switchDraft(($event.target as HTMLSelectElement).value)"><option v-for="[key,draft] in draftOptions" :key="key" :value="key">UID {{draft.uid}} · {{draft.characNo?'角色 #'+draft.characNo:'待选角色'}} · {{draft.items.length}} 条附件</option></select><small>每个玩家及角色独立保留本次会话草稿</small></label><div class="reward-workflow"><ol class="reward-workflow-steps" aria-label="奖励发放流程"><li v-for="(label,index) in workflowLabels" :key="label" :class="{done:index+1<workflowStage,active:index+1===workflowStage}" :aria-current="index+1===workflowStage?'step':undefined"><b aria-hidden="true">{{index+1}}</b><span>{{label}}</span></li></ol><p class="reward-workflow-hint" role="status">{{workflowHint}}</p></div><section class="panel recipient-panel" id="recipient"><div id="mail-recipient" tabindex="-1" :aria-invalid="!!fieldErrors['mail-recipient']" :aria-describedby="fieldErrors['mail-recipient']?'mail-recipient-error':undefined"><FieldError id="mail-recipient-error" :message="fieldErrors['mail-recipient']"/></div><div class="section-title"><h2>收件人</h2><span class="pill">指定单角色 · 不群发</span></div><form class="toolbar" @submit.prevent="findRecipient"><select v-model="recipientSearchType" aria-label="收件人搜索类型" :disabled="busy" @change="recipientResults=[];recipientQueried=false"><option value="account">账号 / UID</option><option value="role">角色名 / 编号</option></select><input id="recipient-query" v-model="recipientSearch" :aria-invalid="!!(fieldErrors['recipient-query']||fieldErrors['mail-recipient'])" :aria-describedby="fieldErrors['recipient-query']?'recipient-query-error':fieldErrors['mail-recipient']?'mail-recipient-error':undefined" aria-label="查找收件账号" :placeholder="recipientSearchType==='role'?'输入角色名或编号':'输入账号名或 UID'" :disabled="busy"><button :disabled="busy">{{recipientSearchType==='role'?'查找角色':'查找账号'}}</button><button type="button" class="ghost" :disabled="busy" @click="go('accounts')">按角色查找 ↗</button></form><FieldError id="recipient-query-error" :message="fieldErrors['recipient-query']"/><p v-if="error&&feedbackScope==='recipient'" class="submit-error">{{error}}</p><div v-if="recipientQueried" class="recipient-options"><button v-for="r in recipientResults" :key="r.charac_no||r.uid" :disabled="busy||!!r.delete_flag" @click="pickRecipient(r)">{{r.charac_no?r.charac_name+' #'+r.charac_no:r.accountname}} · UID {{r.uid}}{{r.delete_flag?'（已删除）':''}}</button><p v-if="!recipientResults.length" class="empty">未找到账号，请换一个关键词。</p></div><div v-if="account" class="recipient-context"><div><span class="muted">当前账号</span><b>{{account.accountname}} <small>UID {{account.uid}}</small></b><span class="status-badge" :class="loginState(account)===1?'success':'neutral'">{{onlineLabel(account)}}</span></div><label><span>收件角色 <em class="required-tag">必填</em></span><select id="mail-role" v-model.number="selectedRole" aria-required="true" :aria-invalid="!!fieldErrors['mail-role']" :aria-describedby="fieldErrors['mail-role']?'mail-role-error':undefined" aria-label="收件角色" :disabled="busy"><option :value="0">请选择收件角色</option><option v-for="r in roles" :key="r.charac_no" :value="r.charac_no" :disabled="!!r.delete_flag">{{r.charac_name}} #{{r.charac_no}} · Lv.{{r.lev}}{{r.delete_flag?'（已删除）':''}}</option></select><FieldError id="mail-role-error" :message="fieldErrors['mail-role']"/><button v-if="selectedRole" type="button" class="ghost" :disabled="busy" @click="openCharacter(selectedRole)">查看收件角色详情</button></label></div><p v-else class="field-hint">尚未选择收件账号。可直接搜索，也可从“账号与角色”带入目标。</p><p v-if="account&&!roles.some(r=>!r.delete_flag)" class="warning">该账号没有可用角色，不能发送物品邮件。</p></section><PlayerShortcuts :revision="playerRevision" :busy="busy||!!pendingId" :current="currentPlayerTarget" @choose="chooseSavedPlayer" @changed="playerRevision++" @expired="clearSession"/><MailWorkbench v-model="mailPane" :count="mailAttachments.length" :quantity="totalQuantity" :gold="Number(mailGold)||0" :has-currencies="hasMailCurrencies" :busy="busy"><template #items><section class="panel catalog-panel"><div class="section-title"><h2>选择物品</h2><button class="ghost" :disabled="busy" @click="go('gifts')">使用礼包模板 ↗</button></div><GmItemPicker :key="'reward-'+workspace.drafts.activeKey" :context-key="'reward-'+workspace.drafts.activeKey" :disabled="busy||!!pendingId" :selected-count="mailAttachments.length" @select="addItem" @loaded="value=>workspace.drafts.syncPvf(value.metadata?.pvf_sha256)" @expired="clearSession"/></section>
    </template><template #draft="{select}"><section class="panel queue-panel"><div class="section-title"><h2>待发放清单 <small>物品、金币或账号货币至少一项</small></h2><button type="button" class="mail-add-items" :disabled="busy" @click="select('items')">添加物品 · {{mailAttachments.length}} / 20</button></div><div v-if="templateId!==null" class="template-binding">绑定模板 #{{templateId}} v{{templateVersion}}<small>{{templateAdjusted?'已临时调整本次奖励；保留来源版本，不修改原模板。':'修改下方奖励只影响本次发放，不修改原模板。'}}</small><button type="button" class="ghost" :disabled="busy||!!pendingId" @click="templateId=null;templateVersion=null;templateAdjusted=false">解除来源绑定</button></div><CurrencyRewardInputs v-model="mailCurrencies" prefix="mail" :busy="busy||!!pendingId" :errors="fieldErrors"/><div id="mail-items" tabindex="-1" :aria-invalid="!!fieldErrors['mail-items']" :aria-describedby="fieldErrors['mail-items']?'mail-items-error':undefined"><FieldError id="mail-items-error" :message="fieldErrors['mail-items']"/><ItemQueue prefix="mail" :errors="fieldErrors" :items="mailAttachments" :busy="busy" @quantity="(n,v)=>mailAttachments[n].quantity=v" @remove="n=>mailAttachments.splice(n,1)"/></div><button v-if="mailAttachments.length" class="ghost full" :disabled="busy" @click="mailAttachments=[]">清空待发清单</button><div class="mail-fields"><label><span>金币附件 <small>可选</small></span><input id="mail-gold" v-model.number="mailGold" type="number" min="0" max="1000000000" step="1" inputmode="numeric" :disabled="busy||!!pendingId" :aria-invalid="!!fieldErrors['mail-gold']" :aria-describedby="fieldErrors['mail-gold']?'mail-gold-error':'mail-gold-hint'"><FieldError id="mail-gold-error" :message="fieldErrors['mail-gold']"/><small id="mail-gold-hint" class="field-hint">0 表示不发；每封最多10亿。大额领取受游戏持币上限影响。</small></label><details class="mail-message-options" :open="mailTextOpen" @toggle="mailTextOpen=($event.target as HTMLDetailsElement).open"><summary>邮件标题与文字 <small>{{mailTitle||message!=='GM rewards'?'已自定义':'可选'}}</small></summary><div class="mail-message-fields"><label><span>邮件标题 <small>可选，作为正文首行发送</small></span><input id="mail-title" v-model="mailTitle" maxlength="40" aria-label="邮件标题" :disabled="busy||!!pendingId" :aria-invalid="!!fieldErrors['mail-title']" :aria-describedby="fieldErrors['mail-title']?'mail-title-error':undefined"><FieldError id="mail-title-error" :message="fieldErrors['mail-title']"/></label><label>邮件文字<input id="mail-message" v-model="message" maxlength="60" :aria-invalid="!!fieldErrors['mail-message']" :aria-describedby="fieldErrors['mail-message']?'mail-message-error':undefined" :disabled="busy" placeholder="例如 GM rewards"><small>部分中文受镜像编码限制；预览拒绝时可改用英文。</small><FieldError id="mail-message-error" :message="fieldErrors['mail-message']"/></label></div></details><label><span>操作原因 <em class="required-tag">必填</em></span><input id="operation-reason" v-model="reason" aria-required="true" :aria-invalid="!!fieldErrors['operation-reason']" :aria-describedby="fieldErrors['operation-reason']?'operation-reason-error':undefined" placeholder="必填，写入不可删除审计" maxlength="200" :disabled="busy"><FieldError id="operation-reason-error" :message="fieldErrors['operation-reason']"/><span class="button-row"><button v-for="preset in ['活动奖励','问题补偿','管理员测试','纠正先前操作']" :key="preset" type="button" :disabled="busy||!!pendingId" @click="reason=preset">{{preset}}</button></span></label></div><div class="queue-summary"><span>合计 {{mailAttachments.length}} 条附件</span><b>{{totalQuantity}} 件 · {{money(mailGold)}} 金币</b></div><p v-if="error&&feedbackScope==='operation'" class="submit-error">{{error}}</p><p v-else-if="notice&&feedbackScope==='operation'" class="submit-success">{{notice}}</p><button class="primary full" :disabled="busy" @click="action='mail';makePreview()">生成预览 →</button><button class="ghost full" :disabled="busy||(!mailAttachments.length&&!(mailGold>0)&&!hasMailCurrencies)||!!pendingId" @click="saveAsTemplate">另存为礼包模板</button><small class="field-hint">仅生成预览，不会投递；确认后才执行。纯文字邮件不支持。</small><details class="operation-guidance"><summary>奖励投递与模板说明</summary><p>账号货币进入账号余额，物品与金币进入角色邮件。金币整封只计一次，可与物品组合；金币和邮件文字可随礼包模板保存。大额金币客户端领取效果未验收，不将数据库投递成功视为已领取。</p></details></section></template></MailWorkbench></div></template>

<style scoped>
.reward-workflow{display:grid;gap:6px;margin-bottom:12px}.reward-workflow-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:0;padding:0;list-style:none}.reward-workflow-steps li{display:flex;align-items:center;justify-content:center;gap:8px;min-width:0;padding:8px;border-bottom:2px solid var(--border-color);font-size:13px;color:var(--text-secondary)}.reward-workflow-steps b{display:grid;place-items:center;width:23px;height:23px;flex-shrink:0;border:1px solid var(--border-color);border-radius:50%;font-size:11px;background:var(--bg-primary)}.reward-workflow-steps .done b{background:var(--primary-10);border-color:var(--primary-30);color:var(--primary-color)}.reward-workflow-steps .active{color:var(--primary-color);border-color:var(--primary-color);font-weight:600}.reward-workflow-steps .active b{background:var(--primary-color);border-color:var(--primary-color);color:var(--primary-contrast)}.reward-workflow-hint{margin:0;color:var(--text-secondary);font-size:12px;text-align:center}
.recipient-panel{padding:14px 18px}.recipient-panel .section-title{margin-bottom:8px}.recipient-panel .toolbar{max-width:850px;margin:8px 0 10px}.recipient-panel .recipient-context{padding:10px 12px;gap:10px 18px}.recipient-panel .recipient-context>div{flex-direction:row;align-items:center;flex-wrap:wrap;gap:5px 9px}.recipient-panel .recipient-context>div>.muted{font-size:12px}.recipient-panel .recipient-context>label{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:4px 8px}.recipient-panel .recipient-context>label>span{grid-column:1/-1}.recipient-panel .recipient-context select{grid-column:1;grid-row:2;padding:7px 9px}.recipient-panel .recipient-context button{grid-column:2;grid-row:2;padding:6px 8px;font-size:12px}.recipient-panel .field-hint{margin:7px 0 0}.gm-workspace>:deep(.player-shortcuts){margin:10px 0 14px;padding:8px 12px}.gm-workspace>:deep(.player-shortcuts .current-target){padding:6px 10px}
@media(max-width:768px){.reward-workflow-steps{gap:4px}.reward-workflow-steps li{flex-direction:column;gap:4px;padding:6px 2px;font-size:11px;text-align:center}.reward-workflow-hint{font-size:11px}.recipient-panel{padding:12px}.recipient-panel .recipient-context{grid-template-columns:minmax(0,1fr);gap:10px}.recipient-panel .recipient-context>label{grid-template-columns:minmax(0,1fr)}.recipient-panel .recipient-context button{grid-column:1;grid-row:auto;justify-self:start}.recipient-panel .toolbar input,.recipient-panel .toolbar select,.recipient-panel .toolbar button{min-height:38px}}
</style>
